+    private void validateRatePlanRules(NewReservation request) {
+        switch (request.ratePlan()) {
+            case CORPORATE:
+                if (request.companyCode().isEmpty()) {
+                    throw new HotelException(ErrorCode.INVALID_REQUEST, "corporate rate requires a company code");
+                }
+                String code = request.companyCode().get();
+                if (!PriceCalculator.CORPORATE_DISCOUNTS.containsKey(code)) {
+                    throw new HotelException(ErrorCode.INVALID_REQUEST, "company code '" + code + "' is not recognized");
+                }
+                break;
+            case WEEKEND_PACKAGE:
+                validateWeekendPackage(request);
+                break;
+            case LONG_STAY:
+                int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
+                if (nights < 7) {
+                    throw new HotelException(ErrorCode.INVALID_REQUEST, "long stay requires at least 7 nights");
+                }
+                break;
+            case STANDARD, NON_REFUNDABLE:
+                break;
+        }
+    }
+
+    private void validateWeekendPackage(NewReservation request) {
+        java.time.DayOfWeek checkInDay = request.checkIn().getDayOfWeek();
+        java.time.DayOfWeek checkOutDay = request.checkOut().getDayOfWeek();
+        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
+
+        if (checkInDay != java.time.DayOfWeek.FRIDAY) {
+            throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package must start on Friday");
+        }
+        if (checkOutDay != java.time.DayOfWeek.SUNDAY) {
+            throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package must end on Sunday");
+        }
+        if (nights != 2) {
+            throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package must be exactly 2 nights");
+        }
+    }
