content.content:
  1	package hotel.reservations;
  2	
  3	import hotel.rooms.Room;
  4	import hotel.rooms.RoomType;
  5	import java.math.BigDecimal;
  6	import java.math.RoundingMode;
  7	import java.time.DayOfWeek;
  8	import java.time.LocalDate;
  9	import java.time.Month;
 10	import java.util.Map;
 11	
 12	/**
 13	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 14	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 15	 * (half-even) at every step.
 16	 */
 17	public final class PriceCalculator {
 18	
 19	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 20	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 21	    static final BigDecimal CORPORATE_DISCOUNT_TECNOSUL = new BigDecimal("0.12");
 22	    static final BigDecimal CORPORATE_DISCOUNT_AGROVALE = new BigDecimal("0.18");
 23	    static final BigDecimal CORPORATE_DISCOUNT_FARMAVIDA = new BigDecimal("0.25");
 24	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
 25	    static final Map<String, BigDecimal> CORPORATE_DISCOUNTS = Map.of(
 26	            "TECNOSUL", CORPORATE_DISCOUNT_TECNOSUL,
 27	            "AGROVALE", CORPORATE_DISCOUNT_AGROVALE,
 28	            "FARMAVIDA", CORPORATE_DISCOUNT_FARMAVIDA);
 29	    static final Map<RoomType, BigDecimal> WEEKEND_PACKAGE_PRICES = Map.of(
 30	            RoomType.STANDARD, new BigDecimal("520.00"),
 31	            RoomType.DELUXE, new BigDecimal("820.00"),
 32	            RoomType.SUITE, new BigDecimal("1200.00"));
 33	
 34	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
 35	        return calculate(room, checkIn, checkOut, ratePlan, null);
 36	    }
 37	
 38	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
 39	        return switch (ratePlan) {
 40	            case WEEKEND_PACKAGE -> calculateWeekendPackage(room, checkIn, checkOut);
 41	            default -> calculateStandardPrice(room, checkIn, checkOut, ratePlan, companyCode);
 42	        };
 43	    }
 44	
 45	    private Price calculateStandardPrice(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
 46	        int nights = 0;
 47	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 48	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 49	            subtotal = subtotal.add(nightPrice(room, night));
 50	            nights++;
 51	        }
 52	        BigDecimal discount = switch (ratePlan) {
 53	            case STANDARD -> cents(BigDecimal.ZERO);
 54	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 55	            case CORPORATE -> cents(subtotal.multiply(CORPORATE_DISCOUNTS.get(companyCode)));
 56	            case LONG_STAY -> cents(subtotal.multiply(LONG_STAY_DISCOUNT));
 57	            case WEEKEND_PACKAGE -> cents(BigDecimal.ZERO); // handled separately
 58	        };
 59	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 60	    }
 61	
 62	    private Price calculateWeekendPackage(Room room, LocalDate checkIn, LocalDate checkOut) {
 63	        BigDecimal total = WEEKEND_PACKAGE_PRICES.get(room.type());
 64	        return new Price(2, total, cents(BigDecimal.ZERO), total);
 65	    }
 66	
 67	    BigDecimal nightPrice(Room room, LocalDate night) {
 68	        BigDecimal nightlyRate = room.nightlyRate();
 69	        if (isHighSeason(night)) {
 70	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
 71	        }
 72	        return cents(nightlyRate);
 73	    }
 74	
 75	    /** High season: from December 15 to the end of February, and the whole of July. */
 76	    static boolean isHighSeason(LocalDate date) {
 77	        Month month = date.getMonth();
 78	        return month == Month.JANUARY
 79	                || month == Month.FEBRUARY
 80	                || month == Month.JULY
