  9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 10	public final class ReservationService {
 11	
 12	    static final String HOTEL_NAME = "Pousada Maré Alta";
 13	
 14	    private final Rooms rooms;
 15	    private final ReservationStore store;
 16	    private final PriceCalculator priceCalculator;
 17	    private final EmailSender emailSender;
 18	
 19	    public ReservationService(
 20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 21	        this.rooms = rooms;
 22	        this.store = store;
 23	        this.priceCalculator = priceCalculator;
 24	        this.emailSender = emailSender;
 25	    }
 26	
 27	    public synchronized Reservation create(NewReservation request) {
 28	        if (!request.checkOut().isAfter(request.checkIn())) {
 29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 30	        }
 31	        if (request.guests() < 1) {
 32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 33	        }
 34	        Room room = rooms.find(request.roomNumber())
 35	                .orElseThrow(() -> new HotelException(
 36	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 37	        if (request.guests() > room.capacity()) {
 38	            throw new HotelException(
 39	                    ErrorCode.CAPACITY_EXCEEDED,
 40	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 41	        }
 42	        validateRatePlanRules(request);
 43	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 44	            throw new HotelException(
 45	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 46	        }
 47	        String companyCode = request.companyCode().orElse(null);
 48	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), companyCode);
 49	        return store.add(request, price);
 50	    }
 51	
 52	    private void validateRatePlanRules(NewReservation request) {
 53	        switch (request.ratePlan()) {
 54	            case CORPORATE:
 55	                if (request.companyCode().isEmpty()) {
 56	                    throw new HotelException(ErrorCode.INVALID_REQUEST, "corporate rate requires a company code");
 57	                }
 58	                String code = request.companyCode().get();
 59	                if (!PriceCalculator.CORPORATE_DISCOUNTS.containsKey(code)) {
 60	                    throw new HotelException(ErrorCode.INVALID_REQUEST, "company code '" + code + "' is not recognized");
 61	                }
 62	                break;
 63	            case WEEKEND_PACKAGE:
 64	                validateWeekendPackage(request);
 65	                break;
 66	            case LONG_STAY:
 67	                int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
 68	                if (nights < 7) {
 69	                    throw new HotelException(ErrorCode.INVALID_REQUEST, "long stay requires at least 7 nights");
 70	                }
 71	                break;
 72	            case STANDARD, NON_REFUNDABLE:
 73	                break;
 74	        }
 75	    }
 76	
 77	    private void validateWeekendPackage(NewReservation request) {
 78	        java.time.DayOfWeek checkInDay = request.checkIn().getDayOfWeek();
 79	        java.time.DayOfWeek checkOutDay = request.checkOut().getDayOfWeek();
 80	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
 81	
 82	        if (checkInDay != java.time.DayOfWeek.FRIDAY) {
 83	            throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package must start on Friday");
 84	        }
 85	        if (checkOutDay != java.time.DayOfWeek.SUNDAY) {
 86	            throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package must end on Sunday");
 87	        }
 88	        if (nights != 2) {
 89	            throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package must be exactly 2 nights");
 90	        }
 91	    }
